"""Bin packing: BFD and budgeted minimum-bin-slack construction (iterative
DFS, no recursion), then a pool-based bin-elimination local search.
The target bin is emptied into a pool. Pool items are reinserted by best fit,
and 1-1, 1-2, 2-1 and 2-2 swaps with bin items are accepted when they
strictly lower the pool's (total size, item count). Failed attempts are
reinserted by best fit and kept if they don't add bins, so loads become
more uneven over time. Everything is validated; FFD is the fallback."""
import time
import random
from bisect import bisect_left, bisect_right, insort

TIME_LIMIT = 1.4
MBS_LIMIT = 0.4
MBS_NODES = 3000


def _ffd(items, capacity):
    order = sorted(range(len(items)), key=lambda i: -items[i])
    free = []
    assignment = [0] * len(items)
    for i in order:
        for b, room in enumerate(free):
            if room >= items[i]:
                free[b] -= items[i]
                assignment[i] = b
                break
        else:
            free.append(capacity - items[i])
            assignment[i] = len(free) - 1
    return assignment


def _lower_bound(items, cap):
    n = len(items)
    a = sorted(items)
    pre = [0]
    for s in a:
        pre.append(pre[-1] + s)
    total = pre[-1]
    best = max(1, -(-total // cap))
    half = cap // 2
    i_half = bisect_right(a, half)
    best = max(best, n - i_half)
    ks = sorted(set(a[:i_half]))
    if len(ks) > 400:
        step = len(ks) / 400.0
        ks = [ks[int(j * step)] for j in range(400)]
    for k in ks:
        i1 = bisect_right(a, cap - k)
        n1 = n - i1
        n2 = i1 - i_half if i1 > i_half else 0
        s2 = pre[i1] - pre[i_half] if i1 > i_half else 0
        ik = bisect_left(a, k)
        s3 = pre[i_half] - pre[ik]
        extra = s3 - (n2 * cap - s2)
        L = n1 + n2 + (-(-extra // cap) if extra > 0 else 0)
        if L > best:
            best = L
    return best


def _bf_insert(s, cap, order, bins, loads):
    """Best fit of `order` on top of existing bins (updates bins and loads)."""
    rooms = sorted((cap - loads[b], b) for b in range(len(bins)) if loads[b] < cap)
    for i in order:
        si = s[i]
        k = bisect_left(rooms, (si, -1))
        if k < len(rooms):
            room, b = rooms.pop(k)
            bins[b].append(i)
            loads[b] += si
            room -= si
        else:
            b = len(bins)
            bins.append([i])
            loads.append(si)
            room = cap - si
        if room > 0:
            insort(rooms, (room, b))


def _bfd(s, cap):
    bins, loads = [], []
    order = sorted(range(len(s)), key=lambda i: -s[i])
    _bf_insert(s, cap, order, bins, loads)
    return bins


def _best_subset(room0, sizes, counts, neg, m, budget):
    best_r = room0
    best = []
    chosen = []
    room = room0
    stack = [bisect_left(neg, -room0)]
    while stack:
        j = stack[-1]
        while j < m and counts[j] == 0:
            j += 1
        if j >= m:
            stack.pop()
            if chosen:
                last = chosen.pop()
                counts[last] += 1
                room += sizes[last]
            continue
        budget -= 1
        if budget < 0:
            break
        stack[-1] = j + 1
        counts[j] -= 1
        chosen.append(j)
        room -= sizes[j]
        if room < best_r:
            best_r = room
            best = chosen[:]
            if room == 0:
                break
        nxt = bisect_left(neg, -room)
        if nxt < j:
            nxt = j
        stack.append(nxt)
    for j in chosen:
        counts[j] += 1
    return best_r, best


def _mbs(s, cap, deadline, node_budget):
    by_size = {}
    for i, v in enumerate(s):
        by_size.setdefault(v, []).append(i)
    sizes = sorted(by_size, reverse=True)
    m = len(sizes)
    counts = [len(by_size[v]) for v in sizes]
    neg = [-v for v in sizes]
    bins = []
    remaining = len(s)
    top = 0
    while remaining:
        while counts[top] == 0:
            top += 1
        if time.perf_counter() > deadline:
            rest = []
            for j in range(m):
                rest.extend(by_size[sizes[j]])
            rest.sort(key=lambda i: -s[i])
            loads = [sum(s[i] for i in b) for b in bins]
            _bf_insert(s, cap, rest, bins, loads)
            return bins
        counts[top] -= 1
        seed = by_size[sizes[top]].pop()
        remaining -= 1
        room = cap - sizes[top]
        best = []
        if room > 0 and remaining:
            _, best = _best_subset(room, sizes, counts, neg, m, node_budget)
        b = [seed]
        for j in best:
            counts[j] -= 1
            b.append(by_size[sizes[j]].pop())
            remaining -= 1
        bins.append(b)
    return bins


def _empty(s, cap, bins, loads, pool, deadline, rng):
    """Try to place every pool item into the existing bins."""
    def place():
        pool.sort(key=lambda i: -s[i])
        rest = []
        nb = len(loads)
        for i in pool:
            si = s[i]
            lim = cap - si
            bb = -1
            bl = -1
            for b in range(nb):
                l = loads[b]
                if bl < l <= lim:
                    bl = l
                    bb = b
                    if l == lim:
                        break
            if bb >= 0:
                bins[bb].append(i)
                loads[bb] += si
            else:
                rest.append(i)
        pool[:] = rest

    def try_swap(b):
        bi = bins[b]
        room = cap - loads[b]
        k = len(bi)
        P = len(pool)
        ssz = [s[i] for i in bi]
        psz = [s[i] for i in pool]
        best = (0, 0)
        mv = None
        # 1-1
        for a in range(k):
            sx = ssz[a]
            lim = sx + room
            for c in range(P):
                sp = psz[c]
                if sx < sp <= lim:
                    key = (sp - sx, 0)
                    if key > best:
                        best = key
                        mv = ((a,), (c,))
        # 1-2
        if P >= 2 and k * P * P <= 3000:
            for a in range(k):
                sx = ssz[a]
                lim = sx + room
                for c in range(P):
                    pc = psz[c]
                    for e in range(c + 1, P):
                        t = pc + psz[e]
                        if sx <= t <= lim:
                            key = (t - sx, 1)
                            if key > best:
                                best = key
                                mv = ((a,), (c, e))
        # 2-1
        if k >= 2 and k * k * P <= 3000:
            for a in range(k):
                for a2 in range(a + 1, k):
                    sx = ssz[a] + ssz[a2]
                    lim = sx + room
                    for c in range(P):
                        sp = psz[c]
                        if sx < sp <= lim:
                            key = (sp - sx, -1)
                            if key > best:
                                best = key
                                mv = ((a, a2), (c,))
        # 2-2
        if k >= 2 and P >= 2 and k * k * P * P <= 6000:
            for a in range(k):
                for a2 in range(a + 1, k):
                    sx = ssz[a] + ssz[a2]
                    lim = sx + room
                    for c in range(P):
                        pc = psz[c]
                        for e in range(c + 1, P):
                            t = pc + psz[e]
                            if sx < t <= lim:
                                key = (t - sx, 0)
                                if key > best:
                                    best = key
                                    mv = ((a, a2), (c, e))
        if mv is None:
            return False
        xa, pcs = mv
        xs = set(bi[a] for a in xa)
        ps = set(pool[c] for c in pcs)
        g = sum(s[i] for i in ps) - sum(s[i] for i in xs)
        newb = [i for i in bi if i not in xs] + [pool[c] for c in pcs]
        newp = [i for i in pool if i not in ps] + [bi[a] for a in xa]
        bins[b] = newb
        pool[:] = newp
        loads[b] += g
        return True

    place()
    if not pool:
        return True
    order = list(range(len(bins)))
    passes = 0
    while pool:
        moved = False
        rng.shuffle(order)
        cnt = 0
        for b in order:
            if not pool:
                break
            cnt += 1
            if (cnt & 15) == 0 and time.perf_counter() > deadline:
                return False
            if try_swap(b):
                moved = True
        if time.perf_counter() > deadline:
            return False
        place()
        if not pool:
            return True
        if not moved:
            return False
        passes += 1
        if passes > 60:
            return False
    return True


def _kick(s, cap, bins, loads, rng):
    B = len(bins)
    if B < 2:
        return
    for _ in range(max(5, B // 8)):
        a = rng.randrange(B)
        b = rng.randrange(B)
        if a == b or not bins[a] or not bins[b]:
            continue
        ia = rng.randrange(len(bins[a]))
        ib = rng.randrange(len(bins[b]))
        x = bins[a][ia]
        y = bins[b][ib]
        d = s[y] - s[x]
        if loads[a] + d <= cap and loads[b] - d <= cap:
            bins[a][ia] = y
            bins[b][ib] = x
            loads[a] += d
            loads[b] -= d


def _local_search(s, cap, init_bins, lb, deadline):
    rng = random.Random(987654321)
    bins = [list(b) for b in init_bins]
    loads = [sum(s[i] for i in b) for b in bins]
    best = [list(b) for b in bins]
    best_n = len(bins)
    fails = 0
    while best_n > lb and time.perf_counter() < deadline:
        B = len(bins)
        if B <= 1:
            break
        cand = sorted(range(B), key=lambda b: (loads[b], len(bins[b])))
        width = min(B, 1 + min(fails, 4))
        t = cand[rng.randrange(width)] if fails else cand[0]
        pool = bins[t]
        last = B - 1
        bins[t] = bins[last]
        loads[t] = loads[last]
        bins.pop()
        loads.pop()
        ok = _empty(s, cap, bins, loads, pool, deadline, rng)
        if ok and not pool:
            fails = 0
            if len(bins) < best_n:
                best = [list(b) for b in bins]
                best_n = len(bins)
        else:
            fails += 1
            pool.sort(key=lambda i: -s[i])
            _bf_insert(s, cap, pool, bins, loads)
            if len(bins) > best_n:
                bins = [list(b) for b in best]
                loads = [sum(s[i] for i in b) for b in bins]
            if fails % 10 == 0:
                _kick(s, cap, bins, loads, rng)
    return best


def _to_assign(bins, n):
    a = [-1] * n
    for bi, b in enumerate(bins):
        for i in b:
            a[i] = bi
    return a


def _valid(a, items, cap):
    if len(a) != len(items):
        return False
    loads = {}
    for b, v in zip(a, items):
        if not isinstance(b, int) or b < 0:
            return False
        loads[b] = loads.get(b, 0) + v
    for v in loads.values():
        if v > cap:
            return False
    return True


def _solve(s, cap, t0):
    n = len(s)
    lb = _lower_bound(s, cap)
    best = _bfd(s, cap)
    if len(best) <= lb:
        return _to_assign(best, n)
    try:
        mb = _mbs(s, cap, t0 + MBS_LIMIT, MBS_NODES)
        if len(mb) < len(best) and sum(len(b) for b in mb) == n:
            best = mb
    except Exception:
        pass
    if len(best) <= lb:
        return _to_assign(best, n)
    try:
        ls = _local_search(s, cap, best, lb, t0 + TIME_LIMIT)
        if len(ls) < len(best) and sum(len(b) for b in ls) == n:
            best = ls
    except Exception:
        pass
    return _to_assign(best, n)


def pack(items, capacity):
    t0 = time.perf_counter()
    n = len(items)
    if n == 0:
        return []
    try:
        s = [int(v) for v in items]
        res = _solve(s, capacity, t0)
        if _valid(res, items, capacity):
            return res
    except Exception:
        pass
    return _ffd(items, capacity)
